<script setup>
import { ref } from 'vue'
import { ArrowLeft, Mail, GraduationCap, Hash, CalendarDays, ChevronRight, Pencil, LogOut, Save, X } from 'lucide-vue-next'
import { useRouter } from 'vue-router'
import { currentUser, updateCurrentUser, logout } from '../services/auth'
import { loadData } from '../services/storage'
const router=useRouter(), editOpen=ref(false)
const organizations=loadData('organizations'), events=loadData('events')
const myOrgs=organizations.slice(0,2), upcoming=events.filter(e=>e.status==='Upcoming').slice(0,2)
const form=ref({name:'',email:'',studentId:'',course:'',year:''})
function openEdit(){form.value={name:currentUser.value?.name||'',email:currentUser.value?.email||'',studentId:currentUser.value?.studentId||'',course:currentUser.value?.course||'',year:currentUser.value?.year||''};editOpen.value=true}
function save(){if(!form.value.name.trim()||!form.value.email.trim())return;updateCurrentUser({...form.value,avatar:form.value.name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()});editOpen.value=false;window.__orgconnectToast?.('Profile updated successfully.')}
function signOut(){logout();router.replace('/login')}
</script>
<template><div class="page profile-page"><button class="back-button" @click="router.back()"><ArrowLeft :size="18"/> Back</button><section class="profile-hero"><div class="avatar profile-avatar">{{currentUser?.avatar||'AS'}}</div><span class="eyebrow">STUDENT PROFILE</span><h1>{{currentUser?.name}}</h1><p>{{currentUser?.email}}</p><button class="btn btn-primary" @click="openEdit"><Pencil :size="16"/> Edit profile</button></section><div class="profile-details"><div><Hash :size="18"/><span><small>Student ID</small><strong>{{currentUser?.studentId||'Not provided'}}</strong></span></div><div><GraduationCap :size="18"/><span><small>Program</small><strong>{{currentUser?.course||'Not provided'}}</strong></span></div><div><CalendarDays :size="18"/><span><small>Year level</small><strong>{{currentUser?.year||'Not provided'}}</strong></span></div><div><Mail :size="18"/><span><small>Email</small><strong>{{currentUser?.email}}</strong></span></div></div><section class="detail-section"><div class="section-heading"><div><span class="eyebrow">MY COMMUNITY</span><h2>Organizations</h2></div><button class="link-button" @click="router.push('/organizations')">Explore</button></div><div class="profile-list"><button v-for="o in myOrgs" :key="o.id" class="simple-row clickable" @click="router.push(`/organizations/${o.id}`)"><div class="org-avatar small">{{o.initials}}</div><div><strong>{{o.name}}</strong><span>{{o.members}} members</span></div><ChevronRight :size="18"/></button></div></section><section class="detail-section"><div class="section-heading"><div><span class="eyebrow">CALENDAR</span><h2>Upcoming events</h2></div></div><div class="profile-list"><div v-for="e in upcoming" :key="e.id" class="simple-row"><div class="row-icon"><CalendarDays :size="18"/></div><div><strong>{{e.title}}</strong><span>{{e.date}} • {{e.time}}</span></div></div></div></section><button class="logout-button" @click="signOut"><LogOut :size="18"/> Log out</button><div v-if="editOpen" class="modal-backdrop" @click.self="editOpen=false"><section class="modal-card"><header class="modal-header"><div><h2>Edit profile</h2><p>Update your student information.</p></div><button class="icon-button" @click="editOpen=false"><X :size="19"/></button></header><form class="modal-form" @submit.prevent="save"><div class="field"><label>Full name *</label><input v-model="form.name" required/></div><div class="field"><label>Email *</label><input v-model="form.email" type="email" required/></div><div class="field"><label>Student ID</label><input v-model="form.studentId"/></div><div class="field"><label>Course / Program</label><input v-model="form.course"/></div><div class="field"><label>Year level</label><select v-model="form.year"><option value="">Select year</option><option>1st Year</option><option>2nd Year</option><option>3rd Year</option><option>4th Year</option></select></div><div class="modal-actions"><button type="button" class="btn btn-secondary" @click="editOpen=false">Cancel</button><button class="btn btn-primary"><Save :size="16"/> Save changes</button></div></form></section></div></div></template>
